const $=id=>document.getElementById(id),money=n=>n==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n),price=n=>n==null?'—':n.toFixed(3),pct=n=>(n*100).toFixed(1)+'%',sign=n=>n>=0?'positive':'negative';
